import Foundation
import Testing
@testable import RunletCore

/// Promote a snippet (#39): Artisan commands, Pest tests, and PHPUnit tests generated from a
/// snippet, and the names and project layout they use. `SnippetPromotionPHPTests` checks the
/// generated files with a local PHP.
struct SnippetPromotionTests {
    private func command(_ code: String, title: String = "Refund order", className: String = "RefundOrder", strictTypes: Bool = false, contextCode: String? = nil, description: String? = nil) -> SnippetPromotion.Output {
        SnippetPromotion.artisanCommand(SnippetPromotion.Source(code: code, contextCode: contextCode, title: title, description: description, strictTypes: strictTypes), className: className, namespace: "App\\Console\\Commands", commandName: SnippetPromotion.commandName(forClass: className))
    }

    private func pest(_ code: String, title: String = "Refund order") -> SnippetPromotion.Output {
        SnippetPromotion.test(SnippetPromotion.Source(code: code, title: title), style: .pest)
    }

    private func phpunit(_ code: String, title: String = "Refund order") -> SnippetPromotion.Output {
        SnippetPromotion.test(SnippetPromotion.Source(code: code, title: title), style: .phpunit, className: "RefundOrderTest", namespace: "Tests\\Feature", baseClass: "Tests\\TestCase")
    }

    // MARK: Whole files

    @Test func writesAnArtisanCommand() {
        let output = command("""
        <?php

        use App\\Models\\Order;

        $order = Order::findOrFail(42); //?
        $order->refund();
        $order->fresh()->status
        """)
        #expect(output.notes.isEmpty)
        #expect(output.source == """
        <?php

        namespace App\\Console\\Commands;

        use App\\Models\\Order;
        use Illuminate\\Console\\Command;

        class RefundOrder extends Command
        {
            /**
             * The name and signature of the console command.
             *
             * @var string
             */
            protected $signature = 'app:refund-order';

            /**
             * The console command description.
             *
             * @var string
             */
            protected $description = 'Refund order';

            /**
             * Execute the console command.
             *
             * Generated by Runlet from a snippet: review it before you run it.
             */
            public function handle()
            {
                $order = Order::findOrFail(42);
                $order->refund();
                dump($order->fresh()->status);
            }
        }

        """)
    }

